import h5py
fn = 'data/RandomizedDelay_Ephys_Behavior/data_structure_JEB11_2022-05-10.mat'
with h5py.File(fn, 'r') as f:
    for path in ['obj/trials', 'obj/clu', 'obj/traj']:
        g = f[path]
        print('\nPATH', path, 'type', type(g).__name__, 'attrs', dict(g.attrs))
        if isinstance(g, h5py.Group):
            keys = list(g.keys())
            print('children', keys)
            for k in keys[:80]:
                sub = g[k]
                print(' ', k, type(sub).__name__, getattr(sub, 'shape', None), getattr(sub, 'dtype', None), dict(sub.attrs))
                if isinstance(sub, h5py.Dataset):
                    try:
                        arr = sub[()]
                        print('   arr shape', getattr(arr, 'shape', None), 'dtype', getattr(arr, 'dtype', None))
                    except Exception as e:
                        print('   read_failed', e)
        else:
            print('dataset shape', g.shape, 'dtype', g.dtype)
            arr = g[()]
            print('arr dtype', arr.dtype, 'shape', arr.shape)
            if arr.dtype == object:
                for i, ref in enumerate(arr.flat[:10]):
                    t = f[ref]
                    print(' ref', i, '->', t.name, type(t).__name__, getattr(t, 'shape', None), getattr(t, 'dtype', None), dict(t.attrs))
